package com.example.editor.codegen;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import org.springframework.stereotype.Component;
import com.example.editor.metamodel.core.MetaAttribute;
import com.example.editor.metamodel.core.MetaClass;
import com.example.editor.metamodel.core.MetaModel;
import com.example.editor.metamodel.core.MetaRelation;
import com.example.editor.metamodel.export.DefaultNeutralMetamodelExportContext;
import com.example.editor.metamodel.export.SqlDdlMetamodelExporter;
import com.example.editor.validation.model.CanonicalModelDocument;
import com.example.editor.validation.model.CanonicalModelElement;
import com.example.editor.validation.model.CanonicalModelRelation;

/** SQL executable projection: schema DDL, constraints and model-instance data in dependency-safe order. */
@Component
public class SqlDataModelCodeGenerationRenderer implements ModelCodeGenerationRenderer {
    private static final Set<String> TARGETS=Set.of("sql-ddl");
    /** Descripción: Ejecuta la operación «targetIds» correspondiente a la responsabilidad de SqlDataModelCodeGenerationRenderer. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ @Override public Set<String> targetIds(){return TARGETS;}
    /** Descripción: Ejecuta la operación «supportedFeatures» correspondiente a la responsabilidad de SqlDataModelCodeGenerationRenderer. Entradas: targetId: identificador que delimita el recurso objetivo. Salida: devuelve el resultado definido por el contrato del método. */ @Override public Set<ModelCodeGenerationFeature> supportedFeatures(String targetId){require(targetId);return Set.of();}
    /** Descripción: Crea o prepara el resultado de «generate» dentro de SqlDataModelCodeGenerationRenderer. Entradas: targetId: identificador que delimita el recurso objetivo; target: dato de entrada necesario para la operación; metamodel: dato de entrada necesario para la operación; model: dato de entrada necesario para la operación; options: configuración que gobierna el comportamiento. Salida: devuelve el resultado definido por el contrato del método. */ @Override public GeneratedModelArtifact generate(String targetId,ModelCodeGenerationTarget target,MetaModel metamodel,CanonicalModelDocument model,ModelCodeGenerationOptions options){
        require(targetId); String ddl = new SqlDdlMetamodelExporter().export(new DefaultNeutralMetamodelExportContext(metamodel, null, null, List.of()));
        StringBuilder out=new StringBuilder("-- HYDRA SQL executable model projection\n-- Schema and constraints are emitted before instance data.\n\n");
        out.append(ddl).append("\n-- Model-instance data\n");
        if(options.includeTraceability()) out.append("-- model: ").append(model.id()).append("\n-- metamodel: ").append(model.metamodelId()).append("\n"); out.append('\n');
        Map<String,MetaClass> classes=metamodel.classes().stream().collect(Collectors.toMap(MetaClass::id,value->value,(a,b)->a,LinkedHashMap::new));
        Map<String,CanonicalModelElement> elements=model.elements().stream().collect(Collectors.toMap(CanonicalModelElement::id,value->value,(a,b)->a,LinkedHashMap::new));
        Map<String,MetaRelation> relations=metamodel.relations().stream().collect(Collectors.toMap(MetaRelation::id,value->value,(a,b)->a,LinkedHashMap::new));
        for(CanonicalModelElement element:model.elements()){MetaClass type=classes.get(element.classId());if(type==null){out.append("-- skipped unknown class for element ").append(element.id()).append('\n');continue;}out.append(insert(type,element)).append('\n');}
        if(!model.relations().isEmpty())out.append("\n-- Relationship assignments\n");
        for(CanonicalModelRelation value:model.relations()){String update=relationUpdate(value,relations.get(value.relationId()),elements,classes);out.append(update).append('\n');}
        String base=safeName(options.artifactName().isBlank()?model.name():options.artifactName());return new GeneratedModelArtifact(base+".sql","text/sql",out.toString().getBytes(StandardCharsets.UTF_8));
    }
    /** Descripción: Ejecuta la operación «insert» correspondiente a la responsabilidad de SqlDataModelCodeGenerationRenderer. Entradas: type: dato de entrada necesario para la operación; element: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private String insert(MetaClass type,CanonicalModelElement element){String table=type.annotations().getOrDefault("sql.table",type.name());Map<String,Object> values=new LinkedHashMap<>();for(MetaAttribute attribute:type.attributes()){Object value=attributeValue(element,attribute);if(value!=null||element.attributes().containsKey(attribute.id())||element.attributes().containsKey(attribute.name()))values.put(attribute.annotations().getOrDefault("sql.column",attribute.name()),value);}if(values.isEmpty())return "INSERT INTO "+qQualified(table)+" DEFAULT VALUES;";return "INSERT INTO "+qQualified(table)+" ("+values.keySet().stream().map(SqlDataModelCodeGenerationRenderer::q).collect(Collectors.joining(", "))+") VALUES ("+values.values().stream().map(SqlDataModelCodeGenerationRenderer::literal).collect(Collectors.joining(", "))+");";}
    /** Descripción: Ejecuta la operación «relationUpdate» correspondiente a la responsabilidad de SqlDataModelCodeGenerationRenderer. Entradas: instance: dato de entrada necesario para la operación; relation: dato de entrada necesario para la operación; elements: dato de entrada necesario para la operación; classes: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private String relationUpdate(CanonicalModelRelation instance,MetaRelation relation,Map<String,CanonicalModelElement> elements,Map<String,MetaClass> classes){if(relation==null)return "-- relation "+instance.id()+" skipped: metamodel relation is unavailable";List<String> sourceColumns=csv(relation.annotations().get("sql.columns")),targetColumns=csv(relation.annotations().get("sql.targetColumns"));if(sourceColumns.size()!=1||targetColumns.size()!=1)return "-- relation "+instance.id()+" preserved in HYDRA but not emitted as UPDATE because the SQL foreign key is not a single-column mapping";CanonicalModelElement source=elements.get(instance.sourceElementId()),target=elements.get(instance.targetElementId());MetaClass sourceClass=source==null?null:classes.get(source.classId()),targetClass=target==null?null:classes.get(target.classId());if(sourceClass==null||targetClass==null)return "-- relation "+instance.id()+" skipped: source or target element is unavailable";MetaAttribute targetAttribute=findByColumn(targetClass,targetColumns.get(0));MetaAttribute sourcePk=primaryKey(sourceClass);if(targetAttribute==null||sourcePk==null)return "-- relation "+instance.id()+" preserved in HYDRA but SQL key metadata is incomplete";Object targetValue=attributeValue(target,targetAttribute),sourceValue=attributeValue(source,sourcePk);if(sourceValue==null)return "-- relation "+instance.id()+" preserved in HYDRA but source primary-key value is missing";String table=sourceClass.annotations().getOrDefault("sql.table",sourceClass.name());String pkColumn=sourcePk.annotations().getOrDefault("sql.column",sourcePk.name());return "UPDATE "+qQualified(table)+" SET "+q(sourceColumns.get(0))+" = "+literal(targetValue)+" WHERE "+q(pkColumn)+" = "+literal(sourceValue)+";";}
    /** Descripción: Ejecuta la operación «primaryKey» correspondiente a la responsabilidad de SqlDataModelCodeGenerationRenderer. Entradas: type: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private MetaAttribute primaryKey(MetaClass type){List<String> declared=csv(type.annotations().get("sql.primaryKeys"));if(!declared.isEmpty()){MetaAttribute found=findByColumn(type,declared.get(0));if(found!=null)return found;}for(MetaAttribute a:type.attributes())if("true".equalsIgnoreCase(a.annotations().get("sql.primaryKey")))return a;for(MetaAttribute a:type.attributes())if("id".equalsIgnoreCase(a.name()))return a;return null;}
    /** Descripción: Obtiene la información correspondiente a «findByColumn» dentro de SqlDataModelCodeGenerationRenderer. Entradas: type: dato de entrada necesario para la operación; column: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private MetaAttribute findByColumn(MetaClass type,String column){for(MetaAttribute a:type.attributes())if(a.annotations().getOrDefault("sql.column",a.name()).equalsIgnoreCase(column))return a;return null;}
    /** Descripción: Ejecuta la operación «attributeValue» correspondiente a la responsabilidad de SqlDataModelCodeGenerationRenderer. Entradas: element: dato de entrada necesario para la operación; attribute: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private Object attributeValue(CanonicalModelElement element,MetaAttribute attribute){if(element==null)return null;if(element.attributes().containsKey(attribute.id()))return element.attributes().get(attribute.id());if(element.attributes().containsKey(attribute.name()))return element.attributes().get(attribute.name());String column=attribute.annotations().get("sql.column");return column==null?null:element.attributes().get(column);}
    /** Descripción: Ejecuta la operación «literal» correspondiente a la responsabilidad de SqlDataModelCodeGenerationRenderer. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String literal(Object value){if(value==null)return "NULL";if(value instanceof Number)return String.valueOf(value);if(value instanceof Boolean b)return b?"TRUE":"FALSE";if(value instanceof Iterable<?> iterable){List<String> values=new ArrayList<>();for(Object item:iterable)values.add(String.valueOf(item));return quote(String.join(",",values));}return quote(String.valueOf(value));}
    /** Descripción: Ejecuta la operación «quote» correspondiente a la responsabilidad de SqlDataModelCodeGenerationRenderer. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String quote(String value){return "'"+value.replace("'","''")+"'";}
    /** Descripción: Ejecuta la operación «q» correspondiente a la responsabilidad de SqlDataModelCodeGenerationRenderer. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String q(String value){return "\""+(value==null?"":value.replace("\"","\"\""))+"\"";}
    /** Descripción: Ejecuta la operación «qQualified» correspondiente a la responsabilidad de SqlDataModelCodeGenerationRenderer. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String qQualified(String value){return java.util.Arrays.stream((value==null?"":value).split("\\.")).map(SqlDataModelCodeGenerationRenderer::q).collect(Collectors.joining("."));}
    /** Descripción: Ejecuta la operación «csv» correspondiente a la responsabilidad de SqlDataModelCodeGenerationRenderer. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static List<String> csv(String value){if(value==null||value.isBlank())return List.of();return java.util.Arrays.stream(value.split(",")).map(String::trim).filter(item->!item.isBlank()).toList();}
    /** Descripción: Ejecuta la operación «safeName» correspondiente a la responsabilidad de SqlDataModelCodeGenerationRenderer. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String safeName(String value){String safe=(value==null?"generated-model":value).replaceAll("[^A-Za-z0-9._-]+","-").replaceAll("-+","-");return safe.isBlank()?"generated-model":safe;}
    /** Descripción: Valida las condiciones necesarias para «require» y rechaza entradas no válidas. Entradas: targetId: identificador que delimita el recurso objetivo. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private static void require(String targetId){if(!TARGETS.contains(targetId))throw new IllegalArgumentException("SQL data renderer does not support target: "+targetId);}
}
